"""Non-repeating writing questions generated by Gemini and checked before use.

Each request creates one new question:
1. A topic is chosen that the student did not see in their last few questions
   and that is not already used in the same mock test session.
2. Gemini returns one question as JSON.
3. The question is checked: topic, task format, word-count statements, length,
   language, exact duplicates and near-duplicates.
4. Only a checked question is saved to question_bank and shown to the student.

These are internal practice questions. They are not official exam prompts.
"""

from __future__ import annotations

import hashlib
import logging
import os
import random
import re
import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any

import database
from config import SOURCE_SINGLE, TASKS, TaskSpec
from services.evaluation_service import (
    EvaluationError,
    EvaluationFormatError,
    build_system_instruction,
    extract_json_object,
    normalize_evaluation,
)
from services.gemini_service import GeminiError, generate_json, is_configured

logger = logging.getLogger(__name__)

QUESTION_TOPICS: tuple[str, ...] = (
    "education",
    "technology",
    "environment",
    "society",
    "health",
    "work",
    "transport",
    "travel",
    "culture",
    "economy",
    "media",
    "food",
    "sport",
    "family",
    "science",
)

# Practice setting for the question difficulty. It is not an official CEFR mapping.
QUESTION_LEVEL: str = os.getenv("QUESTION_LEVEL", "").strip() or "B2"

MAX_GENERATION_ATTEMPTS = 4
RECENT_TOPIC_WINDOW = 3
RECENT_PROMPT_WINDOW = 5
SIMILARITY_WINDOW = 300
SIMILARITY_THRESHOLD = 0.6
MIN_PROMPT_CHARS = 40
MAX_PROMPT_CHARS = 900

QUESTION_SCHEMA = """
CREATE TABLE IF NOT EXISTS question_bank (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    task_key TEXT NOT NULL,
    topic TEXT NOT NULL,
    prompt TEXT NOT NULL,
    prompt_hash TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS question_assignments (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    telegram_id INTEGER NOT NULL,
    question_id INTEGER NOT NULL REFERENCES question_bank(id) ON DELETE CASCADE,
    task_key TEXT NOT NULL,
    session_id INTEGER,
    assigned_at TEXT NOT NULL
);
"""

_TASK_KIND: dict[str, str] = {
    "task_11": "an INFORMAL email to a friend",
    "task_12": "a FORMAL email to a school director or manager",
    "task_2": "a post for an online discussion, giving an opinion with reasons",
}

_REQUIRED_PATTERNS: dict[str, tuple[str, ...]] = {
    "task_11": (r"\binformal\b", r"\bemail\b"),
    "task_12": (r"\bformal\b", r"\bemail\b"),
    "task_2": (r"\bdiscussion\b",),
}

_FORBIDDEN_PATTERNS: dict[str, tuple[str, ...]] = {
    "task_11": (r"\bformal\b",),
    "task_12": (r"\binformal\b",),
    "task_2": (r"\bemail\b",),
}

_WORD_STATEMENT = re.compile(
    r"(\d+)\s*(?:-|–|to)\s*(\d+)\s*words|(\d+)\s*words",
    re.IGNORECASE,
)
_CYRILLIC = re.compile(r"[\u0400-\u04FF]")
_TOKEN = re.compile(r"[a-z']+")


class QuestionError(Exception):
    """User-facing error. The message is in Uzbek."""


class QuestionFormatError(Exception):
    """Internal: a generated question failed the checks. Never shown directly."""


class _DuplicateQuestionError(Exception):
    """Internal: the same question already exists in the bank."""


@dataclass(frozen=True)
class QuestionResult:
    question_id: int
    topic: str
    prompt: str


# ---------------------------------------------------------------------------
# Database setup and queries
# ---------------------------------------------------------------------------

async def init_question_bank() -> None:
    """Create question tables if they do not exist. Call once at startup."""
    async with database.get_connection() as db:
        await db.executescript(QUESTION_SCHEMA)
    logger.info("Question bank is ready")


async def _fetch_column(sql: str, params: tuple[Any, ...]) -> list[Any]:
    async with database.get_connection() as db:
        cursor = await db.execute(sql, params)
        rows = await cursor.fetchall()
    return [row[0] for row in rows]


async def _recent_topics(telegram_id: int) -> list[str]:
    return await _fetch_column(
        """
        SELECT q.topic
        FROM question_assignments a
        JOIN question_bank q ON q.id = a.question_id
        WHERE a.telegram_id = ?
        ORDER BY a.id DESC
        LIMIT ?
        """,
        (telegram_id, RECENT_TOPIC_WINDOW),
    )


async def _recent_prompts(telegram_id: int, limit: int) -> list[str]:
    return await _fetch_column(
        """
        SELECT q.prompt
        FROM question_assignments a
        JOIN question_bank q ON q.id = a.question_id
        WHERE a.telegram_id = ?
        ORDER BY a.id DESC
        LIMIT ?
        """,
        (telegram_id, limit),
    )


async def _task_prompts(task_key: str, limit: int) -> list[str]:
    return await _fetch_column(
        "SELECT prompt FROM question_bank WHERE task_key = ? ORDER BY id DESC LIMIT ?",
        (task_key, limit),
    )


async def _session_topics(session_id: int) -> set[str]:
    topics = await _fetch_column(
        """
        SELECT DISTINCT q.topic
        FROM question_assignments a
        JOIN question_bank q ON q.id = a.question_id
        WHERE a.session_id = ?
        """,
        (session_id,),
    )
    return {str(topic) for topic in topics}


async def get_session_prompt(session_id: int, task_key: str) -> str | None:
    """Return the question given to this mock test session for one task."""
    rows = await _fetch_column(
        """
        SELECT q.prompt
        FROM question_assignments a
        JOIN question_bank q ON q.id = a.question_id
        WHERE a.session_id = ? AND a.task_key = ?
        ORDER BY a.id DESC
        LIMIT 1
        """,
        (session_id, task_key),
    )
    return str(rows[0]) if rows else None


async def _store_question(
    telegram_id: int,
    task_key: str,
    topic: str,
    prompt: str,
    session_id: int | None,
) -> int:
    now = datetime.now(timezone.utc).isoformat(timespec="seconds")
    try:
        async with database.get_connection() as db:
            cursor = await db.execute(
                """
                INSERT INTO question_bank (task_key, topic, prompt, prompt_hash, created_at)
                VALUES (?, ?, ?, ?, ?)
                """,
                (task_key, topic, prompt, prompt_hash(prompt), now),
            )
            question_id = int(cursor.lastrowid)
            await db.execute(
                """
                INSERT INTO question_assignments
                    (telegram_id, question_id, task_key, session_id, assigned_at)
                VALUES (?, ?, ?, ?, ?)
                """,
                (telegram_id, question_id, task_key, session_id, now),
            )
    except sqlite3.IntegrityError as exc:
        raise _DuplicateQuestionError() from exc
    return question_id


# ---------------------------------------------------------------------------
# Checks (pure functions, no database or network)
# ---------------------------------------------------------------------------

def normalize_text(text: str) -> str:
    return " ".join(text.lower().split())


def prompt_hash(prompt: str) -> str:
    return hashlib.sha256(normalize_text(prompt).encode("utf-8")).hexdigest()


def _tokens(text: str) -> set[str]:
    return set(_TOKEN.findall(text.lower()))


def is_too_similar(prompt: str, existing: list[str]) -> bool:
    """True when the prompt is the same as, or very close to, an existing prompt."""
    current = _tokens(prompt)
    if not current:
        return False
    for other in existing:
        if prompt_hash(other) == prompt_hash(prompt):
            return True
        others = _tokens(other)
        if not others:
            continue
        overlap = len(current & others) / len(current | others)
        if overlap >= SIMILARITY_THRESHOLD:
            return True
    return False


def choose_topic(recent_topics: list[str], avoid_topics: set[str]) -> str:
    """Pick a topic not used recently and not used in the same session."""
    recent = set(recent_topics)
    pool = [t for t in QUESTION_TOPICS if t not in avoid_topics and t not in recent]
    if not pool:
        pool = [t for t in QUESTION_TOPICS if t not in avoid_topics]
    if not pool:
        pool = list(QUESTION_TOPICS)
    return random.choice(pool)


def check_word_statements(spec: TaskSpec, prompt: str) -> None:
    """Every word count written in the question must be inside the task range."""
    for match in _WORD_STATEMENT.finditer(prompt):
        for group in match.groups():
            if group is None:
                continue
            number = int(group)
            if not (spec.target_min_words <= number <= spec.target_max_words):
                raise QuestionFormatError(
                    f"So'z soni {number} topshiriq oralig'idan tashqarida "
                    f"({spec.target_min_words}–{spec.target_max_words})."
                )


def validate_question(spec: TaskSpec, topic: str, data: Any) -> str:
    """Check one generated question. Returns the cleaned prompt or raises QuestionFormatError."""
    if not isinstance(data, dict):
        raise QuestionFormatError("AI javobi JSON obyekt emas.")

    got_topic = str(data.get("topic", "")).strip().lower()
    if got_topic != topic:
        raise QuestionFormatError(f"Mavzu noto'g'ri: {got_topic!r}, kutilgan: {topic!r}.")

    prompt = " ".join(str(data.get("prompt", "")).split())
    if not (MIN_PROMPT_CHARS <= len(prompt) <= MAX_PROMPT_CHARS):
        raise QuestionFormatError("Savol uzunligi ruxsat etilgan oraliqdan tashqarida.")
    if _CYRILLIC.search(prompt):
        raise QuestionFormatError("Savolda kirill harflari bor.")

    for pattern in _REQUIRED_PATTERNS[spec.key]:
        if not re.search(pattern, prompt, re.IGNORECASE):
            raise QuestionFormatError(f"Savol topshiriq formatiga mos emas (talab: {pattern}).")
    for pattern in _FORBIDDEN_PATTERNS[spec.key]:
        if re.search(pattern, prompt, re.IGNORECASE):
            raise QuestionFormatError(f"Savol topshiriq formatiga mos emas (taqiqlangan: {pattern}).")

    check_word_statements(spec, prompt)
    return prompt


# ---------------------------------------------------------------------------
# Generation
# ---------------------------------------------------------------------------

def _build_candidate_request(
    spec: TaskSpec,
    topic: str,
    recent_prompts: list[str],
) -> tuple[str, str]:
    system = (
        "You write ONE writing question for an English learner practice app.\n"
        f"Target CEFR level: {QUESTION_LEVEL} (practice setting, not an official mapping).\n"
        f"Task type: {_TASK_KIND[spec.key]}.\n"
        f"Topic (must be exactly this word): {topic}.\n"
        f"Target length of the student's answer: {spec.target_min_words} to "
        f"{spec.target_max_words} words.\n"
        "Rules:\n"
        "- Write the question in English only.\n"
        "- The question is the instruction shown to the student: 2 to 4 sentences "
        "that name the points the student must cover.\n"
        "- Include the target length in the question, for example "
        f"\"Write {spec.target_min_words} to {spec.target_max_words} words.\"\n"
        "- Do not write an answer, a sample email, or hints about wording.\n"
        "- Do not repeat or closely resemble the earlier questions listed by the user.\n"
        f'Return ONLY a JSON object: {{"topic": "{topic}", "prompt": "..."}}'
    )
    if recent_prompts:
        earlier = "\n".join(f"- {prompt}" for prompt in recent_prompts)
    else:
        earlier = "(none)"
    user = f"EARLIER QUESTIONS (do not repeat):\n{earlier}"
    return system, user


async def _generate_candidate(
    spec: TaskSpec,
    topic: str,
    recent_prompts: list[str],
) -> Any:
    system, user = _build_candidate_request(spec, topic, recent_prompts)
    raw = await generate_json(system, user)
    try:
        return extract_json_object(raw)
    except EvaluationFormatError as exc:
        raise QuestionFormatError(str(exc)) from exc


async def get_question(
    telegram_id: int,
    task_key: str,
    session_id: int | None = None,
) -> QuestionResult:
    """Create, check, store and return one new question for this student."""
    if task_key not in TASKS:
        raise QuestionError("Noma'lum topshiriq turi.")
    if not is_configured():
        raise QuestionError("AI savol yaratish sozlanmagan. Administrator bilan bog'laning.")

    spec = TASKS[task_key]
    recent_topics = await _recent_topics(telegram_id)
    session_used = await _session_topics(session_id) if session_id is not None else set()
    recent_prompts = await _recent_prompts(telegram_id, RECENT_PROMPT_WINDOW)
    existing = await _task_prompts(task_key, SIMILARITY_WINDOW)

    for attempt in range(1, MAX_GENERATION_ATTEMPTS + 1):
        topic = choose_topic(recent_topics, session_used)
        try:
            data = await _generate_candidate(spec, topic, recent_prompts)
            prompt = validate_question(spec, topic, data)
            if is_too_similar(prompt, existing):
                raise QuestionFormatError("Savol oldingi savollarga juda o'xshash.")
            question_id = await _store_question(telegram_id, task_key, topic, prompt, session_id)
        except QuestionFormatError as exc:
            logger.info("Generated question rejected (attempt %d/%d): %s",
                        attempt, MAX_GENERATION_ATTEMPTS, exc)
            continue
        except _DuplicateQuestionError:
            logger.info("Duplicate question rejected (attempt %d/%d)",
                        attempt, MAX_GENERATION_ATTEMPTS)
            continue
        except GeminiError as exc:
            raise QuestionError(str(exc)) from exc
        return QuestionResult(question_id=question_id, topic=topic, prompt=prompt)

    raise QuestionError(
        "Yangi savol yaratib bo'lmadi. Iltimos, bir necha daqiqadan keyin qayta urinib ko'ring."
    )


# ---------------------------------------------------------------------------
# Evaluation of a submission written for a specific question
# ---------------------------------------------------------------------------

def _build_evaluation_message(spec: TaskSpec, prompt: str, text: str, word_count: int) -> str:
    return (
        f"TASK TITLE: {spec.title}\n"
        f"TASK INSTRUCTIONS GIVEN TO THE STUDENT:\n{prompt}\n\n"
        f"TARGET LENGTH: {spec.target_min_words} to {spec.target_max_words} words\n"
        f"STUDENT WORD COUNT (computed by the system): {word_count}\n\n"
        "STUDENT TEXT (between the markers below):\n"
        "<<<STUDENT_TEXT_START\n"
        f"{text}\n"
        "STUDENT_TEXT_END>>>"
    )


async def evaluate_prompted_text(
    task_key: str,
    prompt: str,
    text: str,
    word_count: int,
) -> dict[str, Any]:
    """Same rules as evaluation_service.evaluate_text, but with the generated question."""
    spec = TASKS[task_key]
    system_instruction = build_system_instruction(spec)
    user_message = _build_evaluation_message(spec, prompt, text, word_count)

    last_error: EvaluationFormatError | None = None
    for attempt in range(1, 3):
        try:
            raw_text = await generate_json(system_instruction, user_message)
        except GeminiError as exc:
            raise EvaluationError(str(exc)) from exc
        try:
            return normalize_evaluation(extract_json_object(raw_text), text, word_count)
        except EvaluationFormatError as exc:
            logger.warning("Invalid AI evaluation (attempt %d/2): %s", attempt, exc)
            last_error = exc

    raise EvaluationFormatError(
        "AI javobi noto'g'ri formatda keldi. Iltimos, qayta urinib ko'ring."
    ) from last_error


async def evaluate_and_store_prompted(
    telegram_id: int,
    task_key: str,
    prompt: str,
    text: str,
    word_count: int,
    source: str = SOURCE_SINGLE,
    mock_session_id: int | None = None,
) -> tuple[int, dict[str, Any]]:
    """Save the submission, evaluate it against its question and save the result."""
    submission_id = await database.create_submission(
        telegram_id=telegram_id,
        task_type=task_key,
        original_text=text,
        word_count=word_count,
        source=source,
        mock_session_id=mock_session_id,
    )
    result = await evaluate_prompted_text(task_key, prompt, text, word_count)
    await database.save_evaluation(
        submission_id=submission_id,
        estimated_cefr=result["estimated_cefr_level"],
        overall_score=result["overall_score"],
        result=result,
    )
    return submission_id, result
